import type * as Types from '@/types';

export type eventEmitterHandlers = {
  removeAllListeners: (channel: string) => void;
};

export type ElectronLogHandlers = {
  info: (...messages: string[]) => void;
  warn: (...messages: string[]) => void;
  error: (...messages: string[]) => void;
};

export type IpcRendererHandlers = {
  eventEmitter: eventEmitterHandlers;
  listen: <A extends unknown[]>(channel: string, listener: (...args: A) => void) => () => void;
  socketSend: <T extends keyof Types.ClientToServerEvents>(event: T, ...args: Parameters<Types.ClientToServerEvents[T]>) => void;
  socketEmit: <T extends keyof Types.ClientToServerEventsWithAck>(
    event: T,
    payload: Parameters<Types.ClientToServerEventsWithAck[T]>[0],
  ) => Promise<ACK<ReturnType<Types.ClientToServerEventsWithAck[T]>>>;
  getInitialData: (id: string) => unknown | null;
  errorSubmit: (errorId: string, error: Error) => void;
  exit: () => void;
  windowMinimize: (popupId?: string) => void;
  windowMaximize: () => void;
  windowUnmaximize: () => void;
  windowClose: () => void;
  openPopup: <T extends Types.PopupType>(type: T, id: string, initialData: Types.PopupOpenData<T>, force?: boolean) => void;
  closePopup: (id: string) => void;
  closeAllPopups: () => void;
  popupSubmit: (to: string, data?: unknown) => void;
  addAccount: (account: string, data: { isAutoLoginEnabled: boolean; rememberAccount: boolean; password: string }) => void;
  deleteAccount: (account: string) => void;
  setLocale: (locale: Types.Locale) => void;
  addCustomTheme: (theme: Types.Theme) => void;
  deleteCustomTheme: (index: number) => void;
  setCurrentTheme: (theme: Types.Theme | null) => void;
  updateDiscordPresence: (presence: Types.DiscordPresence) => void;
  saveRecord: (record: ArrayBuffer) => void;
  setTrayTitle: (title: string) => void;
  hideDisclaimerNextTime: () => void;
  checkForUpdates: () => void;
  changeEnv: (server: 'prod' | 'dev') => void;
  setIsAutoLoginEnabled: (enable: boolean) => void;
  setIsAutoLaunchEnabled: (enable: boolean) => void;
  setIsAlwaysOnTop: (enable: boolean) => void;
  setIsStatusAutoIdleEnabled: (enable: boolean) => void;
  setStatusAutoIdleMinutes: (minutes: number) => void;
  setIsStatusAutoDndEnabled: (enable: boolean) => void;
  setChannelUIMode: (mode: Types.ChannelUIMode) => void;
  setCloseToTray: (enable: boolean) => void;
  setFont: (font: string) => void;
  setFontSize: (fontSize: number) => void;
  setInputAudioDevice: (deviceId: string) => void;
  setOutputAudioDevice: (deviceId: string) => void;
  setRecordFormat: (format: Types.RecordFormat) => void;
  setRecordSavePath: (path: string) => void;
  setIsMixEffectEnabled: (enabled: boolean) => void;
  setMixEffectType: (key: string) => void;
  setIsAutoMixSettingEnabled: (enabled: boolean) => void;
  setIsEchoCancellationEnabled: (enabled: boolean) => void;
  setIsNoiseCancellationEnabled: (enabled: boolean) => void;
  setIsMicrophoneAmplificationEnabled: (enabled: boolean) => void;
  setIsManualMixMode: (enabled: boolean) => void;
  setMixMode: (key: Types.MixMode) => void;
  setSpeakingMode: (key: Types.SpeakingMode) => void;
  setDefaultSpeakingKey: (key: string) => void;
  setDisableMessageHistory: (enabled: boolean) => void;
  setHotKeyOpenMainWindow: (key: string) => void;
  setHotKeyIncreaseVolume: (key: string) => void;
  setHotKeyDecreaseVolume: (key: string) => void;
  setHotKeyToggleSpeaker: (key: string) => void;
  setHotKeyToggleMicrophone: (key: string) => void;
  setDisableAllSoundEffect: (enabled: boolean) => void;
  setIsEnterVoiceChannelSoundEnabled: (enabled: boolean) => void;
  setIsLeaveVoiceChannelSoundEnabled: (enabled: boolean) => void;
  setIsStartSpeakingSoundEnabled: (enabled: boolean) => void;
  setIsStopSpeakingSoundEnabled: (enabled: boolean) => void;
  setIsReceiveDirectMessageSoundEnabled: (enabled: boolean) => void;
  setIsReceiveChannelMessageSoundEnabled: (enabled: boolean) => void;
  setIsAutoCheckForUpdatesEnabled: (enabled: boolean) => void;
  setUpdateCheckInterval: (interval: number) => void;
  setUpdateChannel: (channel: string) => void;
  runNetworkDiagnosis: (params: { domains: string[]; duration?: number }) => Promise<Types.FullReport | { error: string }>;
  cancelNetworkDiagnosis: () => void;
  requestSfuDiagnosis: () => void;
  sfuDiagnosisResponse: (info: Types.SfuDiagnosisInfo | null) => void;
  login: (formData: { account: string; password: string }) => Promise<{ success: true; token: string } | { success: false }>;
  logout: () => Promise<void>;
  register: (formData: { account: string; password: string; email: string; username: string; locale: string }) => Promise<{ success: true; message: string } | { success: false }>;
  autoLogin: (token: string) => Promise<{ success: true; token: string } | { success: false }>;
  fetchUser: (params: { userId: string }) => Promise<Types.User | null>;
  fetchUserHotReload: (params: { userId: string }) => Promise<Types.User | null>;
  fetchFriend: (params: { userId: string; targetId: string }) => Promise<Types.Friend | null>;
  fetchFriends: (params: { userId: string }) => Promise<Types.Friend[]>;
  fetchFriendActivities: (params: { userId: string }) => Promise<Types.FriendActivity[]>;
  fetchFriendGroup: (params: { userId: string; friendGroupId: string }) => Promise<Types.FriendGroup | null>;
  fetchFriendGroups: (params: { userId: string }) => Promise<Types.FriendGroup[]>;
  fetchFriendApplication: (params: { receiverId: string; senderId: string }) => Promise<Types.FriendApplication | null>;
  fetchFriendApplications: (params: { receiverId: string }) => Promise<Types.FriendApplication[]>;
  fetchServer: (params: { userId: string; serverId: string }) => Promise<Types.Server | null>;
  fetchServers: (params: { userId: string }) => Promise<Types.Server[]>;
  fetchServerMembers: (params: { serverId: string }) => Promise<Types.Member[]>;
  fetchServerOnlineMembers: (params: { serverId: string }) => Promise<Types.OnlineMember[]>;
  fetchChannel: (params: { userId: string; serverId: string; channelId: string }) => Promise<Types.Channel | null>;
  fetchChannels: (params: { userId: string; serverId: string }) => Promise<Types.Channel[]>;
  fetchChannelMembers: (params: { serverId: string; channelId: string }) => Promise<Types.Member[]>;
  fetchMember: (params: { userId: string; serverId: string; channelId?: string }) => Promise<Types.Member | null>;
  fetchMemberApplication: (params: { userId: string; serverId: string }) => Promise<Types.MemberApplication | null>;
  fetchMemberApplications: (params: { serverId: string }) => Promise<Types.MemberApplication[]>;
  fetchMemberInvitation: (params: { receiverId: string; serverId: string }) => Promise<Types.MemberInvitation | null>;
  fetchMemberInvitations: (params: { receiverId: string }) => Promise<Types.MemberInvitation[]>;
  fetchNotifications: (params: { region: Types.Locale }) => Promise<Types.Notification[]>;
  fetchAnnouncements: (params: { region: Types.Locale }) => Promise<Types.Announcement[]>;
  fetchRecommendServers: (params: { region: Types.Locale }) => Promise<Types.RecommendServer[]>;
  uploadImage: (params: {
    folder: string;
    imageName: string;
    imageUnit8Array: Uint8Array;
    targetServerId?: string;
    targetChannelId?: string;
  }) => Promise<{ imageName: string; imageUrl: string } | null>;
  searchServer: (params: { query: string }) => Promise<Types.Server[]>;
  searchUser: (params: { query: string }) => Promise<Types.User[]>;
  saveImage: (buffer: ArrayBuffer, directory: string, filenamePrefix: string, extension: string) => Promise<string | null>;
  selectRecordSavePath: () => Promise<string | null>;
  enableLoopbackAudio: () => Promise<void>;
  disableLoopbackAudio: () => Promise<void>;
  getAccounts: () => Record<string, { isAutoLoginEnabled: boolean; rememberAccount: boolean; password: string }>;
  getLocale: () => Types.Locale;
  getCustomThemes: () => Types.Theme[];
  getCurrentTheme: () => Types.Theme | null;
  getFontList: () => string[];
  getSystemSettings: () => Types.SystemSettings | null;
  getIsAutoLoginEnabled: () => boolean;
  getIsAutoLaunchEnabled: () => boolean;
  getIsAlwaysOnTop: () => boolean;
  getIsStatusAutoIdleEnabled: () => boolean;
  getStatusAutoIdleMinutes: () => number;
  getIsStatusAutoDndEnabled: () => boolean;
  getChannelUIMode: () => Types.ChannelUIMode;
  getCloseToTray: () => boolean;
  getFont: () => string;
  getFontSize: () => number;
  getInputAudioDevice: () => string;
  getOutputAudioDevice: () => string;
  getRecordFormat: () => Types.RecordFormat;
  getRecordSavePath: () => string;
  getIsMixEffectEnabled: () => boolean;
  getMixEffectType: () => string;
  getIsAutoMixSettingEnabled: () => boolean;
  getIsEchoCancellationEnabled: () => boolean;
  getIsNoiseCancellationEnabled: () => boolean;
  getIsMicrophoneAmplificationEnabled: () => boolean;
  getIsManualMixMode: () => boolean;
  getMixMode: () => Types.MixMode;
  getSpeakingMode: () => Types.SpeakingMode;
  getDefaultSpeakingKey: () => string;
  getDisableMessageHistory: () => boolean;
  getHotKeyOpenMainWindow: () => string;
  getHotKeyIncreaseVolume: () => string;
  getHotKeyDecreaseVolume: () => string;
  getHotKeyToggleSpeaker: () => string;
  getHotKeyToggleMicrophone: () => string;
  getDisableAllSoundEffect: () => boolean;
  getIsEnterVoiceChannelSoundEnabled: () => boolean;
  getIsLeaveVoiceChannelSoundEnabled: () => boolean;
  getIsStartSpeakingSoundEnabled: () => boolean;
  getIsStopSpeakingSoundEnabled: () => boolean;
  getIsReceiveDirectMessageSoundEnabled: () => boolean;
  getIsReceiveChannelMessageSoundEnabled: () => boolean;
  getIsAutoCheckForUpdatesEnabled: () => boolean;
  getUpdateCheckInterval: () => number;
  getUpdateChannel: () => string;
  serverSelect: (data: { serverDisplayId: Types.Server['displayId']; serverId: Types.Server['serverId']; timestamp: number }) => void;
  webRTCSignalStateChange: (formData: { signalState: string; userId: string; channelId: string; info?: unknown }) => void;
  enableLoopbackAudio: () => Promise<void>;
  disableLoopbackAudio: () => Promise<void>;
  syncStoreState: (state: Types.StoreStateSnapshot) => void;
  getStoreState: () => Types.StoreStateSnapshot | null;
};

declare global {
  interface Window {
    ipcRenderer?: IpcRendererHandlers;
    electronLog?: ElectronLogHandlers;
  }
}
